-- Paŝoj al plena posedo : réponses types (« corrigé type » montré aux correcteurs), lot 6 : leçons 21 à 24.
-- Questions sur le texte et analyses de langue (21.3, 22.3, 23.3, 24.3), adjectifs (21.4), phrases à corriger (22.4, 23.4),
-- synonymes (24.4).
-- Rédigées d'après les textes et les réponses cochées « juste » par les correcteurs ; à relire par Emmanuelle.
-- Ne remplace pas une réponse type existante ; peut être rejoué sans risque.
SET NAMES utf8mb4;

UPDATE ekzerceroj SET respondo = 'Oni resumas la intrigon de teatraĵo per la nuntempo, kvazaŭ ĝi okazus ĉiufoje, kiam oni ludas ĝin (rakonta prezenco). Aktive: “Ciganoj ŝtelas iun reĝfilinon.” Sinonimo: princino (aŭ: reĝidino).' WHERE id = 1806 AND ekzerco_id = 221 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Oni faris la barbon el kapra vosto.' WHERE id = 1807 AND ekzerco_id = 221 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ekzemple: Klarigu vian ideon kiel eble plej evidente. Elektu kiel eble plej imitindan modelon. Li vestis sin kiel eble plej neglekte. Ŝi volis verki kiel eble plej originalan rakonton. La iluziisto kaŝis la kartojn kiel eble plej artifike.' WHERE id = 1808 AND ekzerco_id = 221 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'preskaŭ' WHERE id = 1809 AND ekzerco_id = 221 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = '“Bone” priskribas staton, ne econ de la subjekto: “estas bone” (adverbo) signifas, ke la situacio estas bona, kaj “al mi” montras, por kiu. “Mi estas bona” signifus, ke li estas bonkora, virta homo, ne ke li fartas bone.' WHERE id = 1810 AND ekzerco_id = 221 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Fundamente “certa” signifas sendube vera, firme konata aŭ konvinkita (“certa fakto”, “mi estas certa”); do “kun certa dubo” estas iom paradoksa.' WHERE id = 1811 AND ekzerco_id = 221 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = '“Frapis la teleron je la plankon”: je + akuzativo montras la direkton, la lokon kontraŭ kiu oni frapas (= kontraŭ la plankon). “Disŝiris je pecoj”: je montras la rezulton de la ago (= en pecojn).' WHERE id = 1812 AND ekzerco_id = 221 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'La krio disvastiĝis de unu persono al la aliaj kiel infekta malsano: la paniko de la dika sinjorino transiris al ĉiuj ĉeestantoj.' WHERE id = 1813 AND ekzerco_id = 221 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'La homamaso, kiu puŝis sin kaj moviĝis en ĉiuj direktoj, similis al la ondoj de ŝtorma maro.' WHERE id = 1814 AND ekzerco_id = 221 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ĉar ili estas ironiaj: la respondeculo ripetas ĝentilan formulon, sed post la katastrofo li tute ne konsideras Conev amiko.' WHERE id = 1815 AND ekzerco_id = 221 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'karitata (aŭ: sindonema, bonfara, filantropa)' WHERE id = 1856 AND ekzerco_id = 225 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'troiga (aŭ: karikatura)' WHERE id = 1857 AND ekzerco_id = 225 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'eleganta (aŭ: ŝika)' WHERE id = 1858 AND ekzerco_id = 225 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'alarma (aŭ: maltrankviliga, zorgiga)' WHERE id = 1859 AND ekzerco_id = 225 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'senkohera (aŭ: galimatia, sensenca)' WHERE id = 1860 AND ekzerco_id = 225 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'efemera (aŭ: pasema)' WHERE id = 1861 AND ekzerco_id = 225 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'groteska (aŭ: absurdega)' WHERE id = 1862 AND ekzerco_id = 225 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'pia (aŭ: devota)' WHERE id = 1863 AND ekzerco_id = 225 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'sterila' WHERE id = 1864 AND ekzerco_id = 225 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'vaka (aŭ: vakua)' WHERE id = 1865 AND ekzerco_id = 225 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ĉar la esperantistoj predikas reciprokan justecon kaj fratecon inter la popoloj, dum laŭ la gentaj ŝovinistoj patriotismo konsistas en malamo kontraŭ ĉio, kio ne estas nia.' WHERE id = 1867 AND ekzerco_id = 227 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'La vera patriotismo estas parto de la granda tutmonda amo, kiu ĉion konstruas, konservas kaj feliĉigas; la ŝovinismo (pseŭdo-patriotismo) estas parto de la komuna malamo, kiu ĉion detruas kaj instigas homon kontraŭ homo.' WHERE id = 1868 AND ekzerco_id = 227 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ambaŭ predikas amon, do ili neniam povas esti malamikaj inter si.' WHERE id = 1869 AND ekzerco_id = 227 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ke ĉiu homo rajtu kaj povu alligiĝi per sia tuta koro al la tero, kiu lin naskis, kaj ke la homoj vivu pace kaj frate, sen altrudi al si siajn lingvojn kaj morojn, kaj kune celu al unu vero kaj unu feliĉo.' WHERE id = 1870 AND ekzerco_id = 227 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Per sia konstanta kaj senlaca laborado por la frateco kaj la interkompreniĝo inter la popoloj: la estonta feliĉa tempo estos ĝia frukto.' WHERE id = 1871 AND ekzerco_id = 227 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Instrua: oni aŭdas la lingvon kaj komparas sian parolmanieron kun tiu de spertaj esperantistoj. Eduka: la izolitaj esperantistoj konvinkiĝas, ke Esperanto estas viva kaj praktika, kaj revenas hejmen kun nova kuraĝo kaj energio.' WHERE id = 1872 AND ekzerco_id = 227 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'La kongresanoj komparas sian parolmanieron kun tiu de spertaj esperantistoj kaj alportas hejmen modelon de bona parolado; tiel la kongresoj reguligas la uzadon, kaj oni parolas Esperanton egale en ĉiuj landoj.' WHERE id = 1873 AND ekzerco_id = 227 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ne: ĝi havas aŭtonomian vivon kun propra spirito, ne pruntita kaj ne imitita; ĉe bona oratoro oni ne povas diveni lian nacion.' WHERE id = 1874 AND ekzerco_id = 227 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ĝi pruvas al la balbutantoj kaj dubantoj, ke oni povas paroli Esperanton bele kaj flue; ili entuziasmiĝas, revenas hejmen kun nova kuraĝo kaj propagandas pli energie.' WHERE id = 1875 AND ekzerco_id = 227 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Persona opinio. Ekzemple: por ekzerciĝi kaj progresi, por ne ekskludi alilandanojn, por montri al la publiko, ke la lingvo funkcias, por ke la etoso restu internacia.' WHERE id = 1876 AND ekzerco_id = 227 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'La gepatroj de Jozefo tre ĉagreniĝis pro lia maldiligenteco.' WHERE id = 1896 AND ekzerco_id = 231 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Homo plene vivas nur tiam, kiam li havas krean ĝojon en sia ĉiutaga laboro.' WHERE id = 1897 AND ekzerco_id = 231 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'En tiu tempo oni ne vidis tiom da novaj konstruaĵoj, kiel nun.' WHERE id = 1898 AND ekzerco_id = 231 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Boteloj plenaj de akvo estas tre pezaj.' WHERE id = 1899 AND ekzerco_id = 231 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'La ministro enoficigis tiun pastron kiel anstataŭantan episkopon.' WHERE id = 1900 AND ekzerco_id = 231 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Kiam vi bruligas fajron, tre gravas, kian lignon vi surmetas.' WHERE id = 1901 AND ekzerco_id = 231 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Preninte la temanĝon, ni veturis hejmen.' WHERE id = 1902 AND ekzerco_id = 231 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Mi ne scias, ĉu tiu poŝtmarko servis por afrankado.' WHERE id = 1903 AND ekzerco_id = 231 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'La kongreso okazos de la 20-a ĝis la 27-a de majo.' WHERE id = 1904 AND ekzerco_id = 231 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Tiun beston oni nomas talpo.' WHERE id = 1905 AND ekzerco_id = 231 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Mi troviĝis en palmareto.' WHERE id = 1908 AND ekzerco_id = 234 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'La loĝantoj estas komparataj kun birdoj, kiuj ennestiĝas: iliaj malgrandaj dometoj el premita tero similas nestojn.' WHERE id = 1909 AND ekzerco_id = 234 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Pasivaj: subsabligita (kiun la sablo duone kovris), nomata (kiun oni nomas), forrabitaj (kiujn oni forrabis), premita (kiun oni premis). Aktivaj: deveninte (post kiam ĝi devenis), venkakirintoj (tiuj, kiuj akiris per venko), verdantan (kiu verdas, estas verda).' WHERE id = 1910 AND ekzerco_id = 234 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'La dezerto ĉirkaŭas la oazon kiel juvelujo ĉirkaŭas smeraldon: la verda oazo estas valora kaj brila meze de la flavbruna sablo.' WHERE id = 1911 AND ekzerco_id = 234 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = '-id- (ido): kaprido → katido, hundido, ŝafido, reĝido, bovido. -aĵ- (konkreta afero): lignardaĵoj → manĝaĵo, trinkaĵo, novaĵo, dolĉaĵo, konstruaĵo. -ad- (daŭra ago): aŭskultado → parolado, legado, kurado, laborado, kantado. ge- (ambaŭ seksoj): geplendantoj → gepatroj, geedzoj, gefratoj, geamikoj, gesinjoroj. -estr- (ĉefo): vilaĝestro → urbestro, lernejestro, ŝipestro, regnestro, stacidomestro. -ist- (profesio): sklavkomercisto → instruisto, kuracisto, verkisto, fiŝkaptisto, horloĝisto. -ig- (kaŭzi): vidigi → sciigi, mortigi, purigi, plibonigi, ruĝigi.' WHERE id = 1912 AND ekzerco_id = 234 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ekzemple: Li estas vera Krezo (riĉulo). Li estas Don Juan (virinkaptisto). Li estas vera Herkulo (fortulo). Ŝi estas la Florence Nightingale de nia hospitalo. Li estas la Napoleono de la komerco.' WHERE id = 1913 AND ekzerco_id = 234 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = '“Nejuna” signifas, ke ŝi ne plu estas juna, sed ankoraŭ ne maljuna (meza aĝo); “maljuna” signifas, ke ŝi havas grandan aĝon. “Nejuna” estas ankaŭ pli ĝentila, mildigita esprimo.' WHERE id = 1914 AND ekzerco_id = 234 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'post-e-ul-ar-o: la aro de la personoj, kiuj venos poste (la estontaj generacioj). Antonimo: antaŭularo (aŭ: praularo, prapatroj).' WHERE id = 1915 AND ekzerco_id = 234 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ŝiaj okuloj estas grandaj, mildaj kaj iom senesprimaj kiel tiuj de bovo. Per la sufikso -ec- oni farus simplan komparon: “mallevante siajn bovecajn okulojn”.' WHERE id = 1916 AND ekzerco_id = 234 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'La aŭtoro atribuas homan geston al la dunoj: en la vespera lumo ili heliĝas kaj ŝajnas agrable rideti al la suno.' WHERE id = 1917 AND ekzerco_id = 234 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ĉar la tempo de la subordigita propozicio estas rilata al la ĉefverbo: en la momento de la konkludo, la vojaĝanto ankoraŭ estis venanta.' WHERE id = 1918 AND ekzerco_id = 234 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'La artikolo montras, ke temas pri konataj, tradiciaj tri tasoj: la rito postulas ĝuste tri tasojn.' WHERE id = 1919 AND ekzerco_id = 234 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'La kongreso komenciĝis la 3-an de aŭgusto.' WHERE id = 1921 AND ekzerco_id = 236 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'En la akceptejo regis vigla atmosfero.' WHERE id = 1922 AND ekzerco_id = 236 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Kiel abonanto de via gazeto, mi petas vin publikigi mian anonceton. (“Kiel abonanto” rilatas al la subjekto de la verbo: en la originalo tio estus “vi”, la redaktoro.)' WHERE id = 1923 AND ekzerco_id = 236 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Li faris decidon, kiu mutigis lian edzinon pro mirego.' WHERE id = 1924 AND ekzerco_id = 236 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'La anekdotoj, kiujn li skribis dum sia libertempo, estas tre amuzaj.' WHERE id = 1925 AND ekzerco_id = 236 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'La sekretario elparolis vortojn jam de longe atenditajn.' WHERE id = 1926 AND ekzerco_id = 236 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ĉesigu vian petoladon!' WHERE id = 1927 AND ekzerco_id = 236 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Niaj gastoj ankoraŭ ne alvenis.' WHERE id = 1928 AND ekzerco_id = 236 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Mia amiko montris al mi gravan dokumenton.' WHERE id = 1929 AND ekzerco_id = 236 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Multaj ribelintoj estas en la karceroj (aŭ: en la malliberejoj).' WHERE id = 1930 AND ekzerco_id = 236 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ĉi tie -um- esprimas agon iel rilatan al la vosto: la pavo etendas kaj montras sian voston por fanfaroni. Do li paradas kaj fanfaronas kiel pavo.' WHERE id = 1940 AND ekzerco_id = 240 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'brakumi' WHERE id = 1941 AND ekzerco_id = 240 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ekzemple: “Mia kolego estas tre longa” (laborkunulo aŭ granda kolo); “La esperanto alvenis” (la lingvo aŭ persono, kiu esperas); “Li parolis persone” (mem aŭ per sono); “Ŝi rigardis la vilaĝon” (vilaĝo aŭ vila aĝo, kiel en la poemo).' WHERE id = 1942 AND ekzerco_id = 240 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = '“Ĉien” signifas “al ĉiuj lokoj”: la akuzativo montras la direkton de la movo.' WHERE id = 1943 AND ekzerco_id = 240 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Mankas la ĉefverbo: la frazo havas nur participojn kaj adverbojn (“plendetante, havante, rampetante… nevolonte al lernejo”), sen finita verbo kiel “iras”.' WHERE id = 1944 AND ekzerco_id = 240 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'La amanto sopiras kaj ĝemas tiel forte kaj varme, kvazaŭ li elspirus fajron kaj fumon kiel fornego.' WHERE id = 1945 AND ekzerco_id = 240 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'sakroj (aŭ: blasfemoj, malbenoj)' WHERE id = 1946 AND ekzerco_id = 240 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'kanono' WHERE id = 1947 AND ekzerco_id = 240 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Persona opinio. Ekzemple: ne tre, ĉar leopardo ne vere havas barbon; eble la tradukinto pensis pri ĝiaj lipharoj, aŭ pri la sovaĝa kaj timiga aspekto de la soldato.' WHERE id = 1948 AND ekzerco_id = 240 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'bonkoreco (aŭ: favoremo, afableco)' WHERE id = 1964 AND ekzerco_id = 243 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'koketa' WHERE id = 1965 AND ekzerco_id = 243 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'pantoflo' WHERE id = 1966 AND ekzerco_id = 243 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'gajno (aŭ: enkasigo, profito)' WHERE id = 1967 AND ekzerco_id = 243 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'verdikto' WHERE id = 1968 AND ekzerco_id = 243 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'fripono (aŭ: fiulo)' WHERE id = 1969 AND ekzerco_id = 243 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'oratoro' WHERE id = 1970 AND ekzerco_id = 243 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'aktoro' WHERE id = 1971 AND ekzerco_id = 243 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'duno' WHERE id = 1972 AND ekzerco_id = 243 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'bieno' WHERE id = 1973 AND ekzerco_id = 243 AND COALESCE(respondo, '') = '';

-- Vérification
SELECT ekzerco_id, COUNT(*) AS demandoj, SUM(COALESCE(respondo, '') <> '') AS kun_respondo FROM ekzerceroj
  WHERE ekzerco_id IN (221, 225, 227, 231, 234, 236, 240, 243) AND forigita = 0 GROUP BY ekzerco_id;
